export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.15, 0.15, 0.15).toLinearSpace();
  scene.useRightHandedSystem = true;

  const hdrCubeTexture = new BABYLON.HDRCubeTexture("/images/textures/country.hdr", scene, 128, false, true, false, true);
  scene.environmentTexture = hdrCubeTexture;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 0.384, 0.06));
  camera.alpha = 0.859;
  camera.beta = 1.298;
  camera.lowerBetaLimit = 0.9;
  camera.upperBetaLimit = 1.548;
  camera.radius = 3.88;
  camera.lowerRadiusLimit = 2.865;
  camera.upperRadiusLimit = 5.95;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.1;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  const dpp = new BABYLON.DefaultRenderingPipeline("dpp", true, scene);
  dpp.fxaaEnabled = true;
  dpp.glowLayerEnabled = true;
  dpp.bloomEnabled = true;
  dpp.chromaticAberrationEnabled = true;
  dpp.imageProcessing.contrast = 1.5;
  dpp.imageProcessing.vignetteEnabled = true;
  dpp.imageProcessing.vignetteColor = BABYLON.Color3.Red();
  dpp.imageProcessing.vignetteWeight = 4;

  let rootMesh;
  let wheel_F = null;
  let wheelChain_F = null;
  let wheel_B = null;
  let wheelChain_B = null;

  const roadMat = new BABYLON.StandardMaterial("roadMat", scene);
  roadMat.diffuseTexture = new BABYLON.Texture("/images/textures/speckles.jpg", scene);
  roadMat.diffuseTexture.uScale = 1;
  roadMat.diffuseTexture.vScale = 10;

  const road = BABYLON.MeshBuilder.CreatePlane("road", { width: 8, height: 100 }, scene);
  road.material = roadMat;
  road.rotation.x = Math.PI / 2;
  road.position.y = 0;

  scene.registerBeforeRender(() => {
    roadMat.diffuseTexture.vOffset += 0.05;
  });

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "ghost rider bike.glb").then((result) => {
    rootMesh = result.meshes[0];
    const baseY = rootMesh.position.y;
    const baseX = rootMesh.position.x;

    wheel_F = rootMesh.getChildMeshes(false, (m) => m.name === "Wheel_F")[0];
    wheelChain_F = rootMesh.getChildMeshes(false, (m) => m.name === "WheelChain_F")[0];
    wheel_B = rootMesh.getChildMeshes(false, (m) => m.name === "Wheel_B")[0];
    wheelChain_B = rootMesh.getChildMeshes(false, (m) => m.name === "WheelChain_B")[0];

    wheel_F.material.emissiveColor = BABYLON.Color3.FromHexString("#060100");
    wheelChain_F.material.emissiveColor = BABYLON.Color3.FromHexString("#140401");

    if (wheel_F.rotationQuaternion) {
      wheel_F.rotationQuaternion = null;
    }
    if (wheelChain_F.rotationQuaternion) {
      wheelChain_F.rotationQuaternion = null;
    }
    if (wheel_B.rotationQuaternion) {
      wheel_B.rotationQuaternion = null;
    }
    if (wheelChain_B.rotationQuaternion) {
      wheelChain_B.rotationQuaternion = null;
    }

    fire(wheel_F, wheel_B.position, wheel_F.position);
    fire(wheel_B, wheel_B.position, wheel_F.position);

    let rotAngle = 0;
    const speed = 15;
    let shakeTime = 0;
    let lastEmitTime = 0;
    const emitInterval = 80;

    scene.registerBeforeRender(() => {
      const dt = engine.getDeltaTime() * 0.001;
      rotAngle += dt * 3;
      shakeTime += dt;

      if (wheel_F && wheelChain_F) {
        wheel_F.rotation.x = rotAngle * speed;
        wheelChain_F.rotation.x = rotAngle * speed;
      }
      if (wheel_B && wheelChain_B) {
        wheel_B.rotation.x = rotAngle * speed;
        wheelChain_B.rotation.x = rotAngle * speed;
      }

      const frequency = 4.5;
      const amplitude = 0.02;

      const offsetY = Math.sin(shakeTime * frequency) * amplitude + (Math.random() - 0.5) * 0.005;
      const offsetX = Math.cos(shakeTime * frequency * 0.9) * amplitude * 0.5 + (Math.random() - 0.5) * 0.005;

      rootMesh.position.y = baseY + offsetY;
      rootMesh.position.x = baseX + offsetX;

      dpp.glowLayer.intensity = Math.sin(shakeTime) * 1.7;
    });

    scene.registerBeforeRender(() => {
      const now = Date.now();
      if (now - lastEmitTime > emitInterval) {
        lastEmitTime = now;

        createSkidFlame(wheel_F.getAbsolutePosition().clone().add(new BABYLON.Vector3(0, -0.3, 0)));
        createSkidFlame(wheel_B.getAbsolutePosition().clone().add(new BABYLON.Vector3(0, -0.3, 0)), -11);
      }
    });

    var mb = new BABYLON.MotionBlurPostProcess("mb", scene, 1.0, camera);
  });

  let color1 = BABYLON.Color3.FromInts(249, 115, 0);
  let color2 = BABYLON.Color3.FromInts(222, 93, 54);
  let textureParticule = new BABYLON.Texture("/images/textures/particle_01.png");

  function fire(emitter, start, end) {
    var angle = Math.atan2(start.z - end.z, start.x - end.x);

    var material = new BABYLON.StandardMaterial("player_spell");
    material.diffuseColor = color1;
    material.alpha = 0.1;

    var projectile = BABYLON.MeshBuilder.CreateSphere("Projectile", { segments: 4, diameter: 0.01 }, scene);
    projectile.material = material;
    projectile.setParent(emitter);
    projectile.position = new BABYLON.Vector3(0, 0.27, 0);

    projectile.rotation.y = Math.PI / 2 - angle;

    var particleSystemTrail = new BABYLON.ParticleSystem("particlesTrail", 200, scene);
    particleSystemTrail.particleTexture = textureParticule;
    particleSystemTrail.emitter = projectile;
    particleSystemTrail.color1 = BABYLON.Color4.FromColor3(color1);
    particleSystemTrail.color2 = BABYLON.Color4.FromColor3(color2);
    particleSystemTrail.colorDead = new BABYLON.Color4(0, 0, 0, 0.0);
    particleSystemTrail.minSize = 0.3;
    particleSystemTrail.maxSize = 0.6;
    particleSystemTrail.minLifeTime = 0.03;
    particleSystemTrail.maxLifeTime = 0.04;
    particleSystemTrail.emitRate = 800;
    particleSystemTrail.createPointEmitter(new BABYLON.Vector3(-1, 0, 10), new BABYLON.Vector3(0, 0, 0));
    particleSystemTrail.minEmitPower = 1;
    particleSystemTrail.maxEmitPower = 2;
    particleSystemTrail.start();

    var particleSystem = new BABYLON.ParticleSystem("particles", 200, scene);
    particleSystem.particleTexture = new BABYLON.Texture("/images/textures/sparkle.png");
    particleSystem.emitter = emitter;
    particleSystem.color1 = BABYLON.Color4.FromColor3(color1);
    particleSystem.color2 = BABYLON.Color4.FromColor3(color2);
    particleSystem.colorDead = new BABYLON.Color4(0, 0, 0, 0.0);
    particleSystem.minSize = 0.05;
    particleSystem.maxSize = 0.1;
    particleSystem.gravity = new BABYLON.Vector3(0, 0, -50);
    particleSystem.minEmitBox = new BABYLON.Vector3(0, 0, 0);
    particleSystem.maxEmitBox = new BABYLON.Vector3(0, 0, 0);
    particleSystem.direction1 = new BABYLON.Vector3(1, 1.5, -4);
    particleSystem.direction2 = new BABYLON.Vector3(-1, -1.5, -4);
    particleSystem.minLifeTime = 0.1;
    particleSystem.maxLifeTime = 0.3;
    particleSystem.emitRate = 150;

    particleSystem.start();
  }

  function createSkidFlame(position, directionZ) {
    const flame = new BABYLON.ParticleSystem("skidFlame", 100, scene);
    flame.particleTexture = new BABYLON.Texture("/images/textures/cloud.png", scene);

    const emitterNode = new BABYLON.TransformNode("skidEmitter", scene);
    emitterNode.position.copyFrom(position);
    flame.emitter = emitterNode;

    flame.minEmitBox = BABYLON.Vector3.Zero();
    flame.maxEmitBox = BABYLON.Vector3.Zero();

    flame.color1 = new BABYLON.Color4(1, 0.6, 0.1, 1.0);
    flame.color2 = new BABYLON.Color4(1, 0.2, 0.05, 0.5);
    flame.colorDead = new BABYLON.Color4(0, 0, 0, 0);

    flame.minSize = 0.1;
    flame.maxSize = 0.25;

    flame.minLifeTime = 0.3;
    flame.maxLifeTime = 0.5;

    flame.emitRate = 100;
    flame.blendMode = BABYLON.ParticleSystem.BLENDMODE_ADD;

    flame.gravity = BABYLON.Vector3.Zero();

    const randomOffset = Math.random() * 4 - 2;
    flame.direction1 = directionZ ? new BABYLON.Vector3(randomOffset, 0, directionZ) : new BABYLON.Vector3(randomOffset, 0, -3);
    flame.direction2 = directionZ ? new BABYLON.Vector3(-randomOffset, 0, directionZ) : new BABYLON.Vector3(-randomOffset, 0, -5);

    flame.disposeOnStop = true;
    flame.manualEmitCount = directionZ ? 20 : 50;
    flame.updateSpeed = directionZ ? 0.004 : 0.01;
    flame.start();

    setTimeout(() => emitterNode.dispose(), 1000);
  }
  return scene;
}
